function isDarkMode(){return document.documentElement.classList.contains('dark');}
function loadHighlightTheme(){const themeLink=document.getElementById('highlight-theme');if(themeLink){themeLink.remove();}
const link=document.createElement('link');link.id='highlight-theme';link.rel='stylesheet';link.href=isDarkMode()?'https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/vs2015.min.css':'https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/vs.min.css';document.head.appendChild(link);}
const script=document.createElement('script');script.src='https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.8.0/highlight.min.js';script.onload=function(){hljs.highlightAll();loadHighlightTheme();const observer=new MutationObserver(function(mutations){mutations.forEach(function(mutation){if(mutation.attributeName==='class'){loadHighlightTheme();}});});observer.observe(document.documentElement,{attributes:true,attributeFilter:['class']});};document.head.appendChild(script);;